#!/bin/bash
# User data for a team VM of the race (generated by tools/race_launch.py user-data).
# The VM runs the team's own harness headless for the whole week. It holds only the team's
# capped provider key and its broker token, no GitHub or cloud credential: it publishes its
# status, logs and a git bundle of its branch over plain HTTP under a random path,
# http://IP:8000/__TOKEN__/, and the user's launcher collects the bundle and pushes race/<team>.
#
# Placeholders: __TOKEN__, __TEAM__, __REPO__, __TAG__, __DEADLINE__ (epoch seconds),
# __ENV_B64__ (environment file), __SETUP_B64__ (harness install and login commands).
set -u
export HOME=/root
WWW=/srv/www; OUT=$WWW/__TOKEN__; mkdir -p "$OUT"
: > "$WWW/index.html"
status() { echo "$(date -u +%FT%TZ) $*" >> "$OUT/status.txt"; }
exec >> "$OUT/setup.log" 2>&1
status "boot __TEAM__"
(cd "$WWW" && nohup python3 -m http.server 8000 >/dev/null 2>&1 &)

echo "__ENV_B64__" | base64 -d > /etc/race.env && chmod 600 /etc/race.env
set -a; . /etc/race.env; set +a

export DEBIAN_FRONTEND=noninteractive
apt-get update -q && apt-get install -y -q git python3-venv python3-pip curl nodejs npm \
  || { status "FAILED apt"; exit 1; }
cd /opt && git clone -q "__REPO__" milady && cd milady && git checkout -q "__TAG__" \
  && git checkout -q -b "race/__TEAM__" || { status "FAILED clone"; exit 1; }
git config user.name "race-__TEAM__" && git config user.email "race-__TEAM__@localhost"
python3 -m venv /opt/venv && . /opt/venv/bin/activate
pip install -q -r infra/env/requirements.txt && pip install -q --no-deps -e . || { status "FAILED pip"; exit 1; }
echo "__SETUP_B64__" | base64 -d > /opt/setup.sh && bash /opt/setup.sh || { status "FAILED harness setup"; exit 1; }
status "ready: $(nproc) vCPU, harness installed"

publish() { git add -A && git commit -q -m "race __TEAM__: $1" || true
            git bundle create "$OUT/branch.bundle.tmp" "race/__TEAM__" && mv "$OUT/branch.bundle.tmp" "$OUT/branch.bundle"; }

# 1. Preflight: one minimal API call per (model, effort) pair of the roles.
python3 tools/check_calls.py preflight --provider "$MILADY_PROVIDER" > "$OUT/preflight.txt" 2>&1 \
  && status "preflight passed" || status "preflight FAILED (see preflight.txt)"

# 2. Autonomy exam: the harness alone must call every role with the prescribed model and effort.
SINCE=$(date -u +%Y%m%dT%H%M%S)
python3 tools/race_launch.py run-main --team "__TEAM__" --prompt-file research/preflight-exam.md \
  > "$OUT/exam-run.log" 2>&1
python3 tools/check_calls.py exam --provider "$MILADY_PROVIDER" --since "$SINCE" > "$OUT/exam.txt" 2>&1 \
  && status "exam passed" || status "exam FAILED (see exam.txt)"
git checkout -q -- . && git clean -fdq -e research/model-calls.jsonl -e research/calls/
publish "preflight and exam"

# 3. The race: invoke the harness again and again until the deadline. Three short failures
# in a row (usually the spending cap) end the team's race.
i=0; fails=0
while [ "$(date +%s)" -lt "__DEADLINE__" ] && [ "$fails" -lt 3 ]; do
  i=$((i + 1)); T0=$(date +%s)
  status "iteration $i started"
  python3 tools/race_launch.py run-main --team "__TEAM__" --prompt-file race/BRIEF.md --iteration "$i" \
    >> "$OUT/race.log" 2>&1; rc=$?
  dt=$(( $(date +%s) - T0 ))
  if [ "$rc" -ne 0 ] && [ "$dt" -lt 300 ]; then fails=$((fails + 1)); else fails=0; fi
  status "iteration $i ended rc=$rc after $dt s"
  publish "iteration $i"
done
publish "final"
if [ "$fails" -ge 3 ]; then status "STOPPED: harness failed 3 times in a row (spending cap?)"; else status "DONE: deadline reached"; fi
